CREATE TABLE accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, display_name VARCHAR(200) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, wallet_balance DECIMAL(12,2) NOT NULL);
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL UNIQUE, price DECIMAL(12,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, subtotal DECIMAL(12,2) NOT NULL, tier_discount DECIMAL(12,2) NOT NULL, coupon_discount DECIMAL(12,2) NOT NULL, total DECIMAL(12,2) NOT NULL, payment_method VARCHAR(20) NOT NULL, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_orders_account FOREIGN KEY (account_id) REFERENCES accounts(id));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, unit_price DECIMAL(12,2) NOT NULL, quantity INT NOT NULL, CONSTRAINT fk_items_order FOREIGN KEY (order_id) REFERENCES orders(id), CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE wallet_transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, order_id BIGINT NULL, amount DECIMAL(12,2) NOT NULL, type VARCHAR(20) NOT NULL, balance_after DECIMAL(12,2) NOT NULL, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_wallet_account FOREIGN KEY (account_id) REFERENCES accounts(id), CONSTRAINT fk_wallet_order FOREIGN KEY (order_id) REFERENCES orders(id));
CREATE INDEX idx_orders_account_created ON orders(account_id, created_at);
CREATE INDEX idx_wallet_account_created ON wallet_transactions(account_id, created_at);
